from hwlib import M, P, part, SET

F = lambda n: f"homework/img/hw05-{n}.png"

HW05 = SET("hw05", "HW05 · Ch 25 Capacitance", "CST homework05 (Chapter 25), mxhuang@scut.edu.cn", [
  M(1, "A parallel-plate capacitor C has a charge Q. The actual charges on its plates are:",
    ["$Q, Q$", "$Q/2, Q/2$", "$Q, -Q$", "$Q/2, -Q/2$", "$Q, 0$"], "C",
    "A capacitor's 'charge $Q$' means $+Q$ on one plate and $-Q$ on the other; the capacitor as a whole is neutral."),
  M(2, "Each plate of a capacitor stores a charge of magnitude 1 mC when a 100 V potential difference is applied. The capacitance is:",
    ["5 μF", "10 μF", "50 μF", "100 μF", "none of these"], "B",
    r"$C = \frac{Q}{V} = \frac{1\times10^{-3}}{100} = 1\times10^{-5}$ F $= 10$ μF."),
  M(3, r"A parallel-plate capacitor has plate area 0.2 m² and separation 0.1 mm. If each plate has charge $4\times10^{-6}$ C, the potential difference is approximately:",
    ["0 V", r"$4\times10^{-2}$ V", r"$2\times10^{2}$ V", r"$2\times10^{5}$ V", r"$4\times10^{8}$ V"], "C",
    r"$C = \frac{\varepsilon_0A}{d} = \frac{(8.85\times10^{-12})(0.2)}{1\times10^{-4}} = 1.77\times10^{-8}$ F, so $V = \frac{Q}{C} = \frac{4\times10^{-6}}{1.77\times10^{-8}} \approx 2\times10^{2}$ V."),
  M(4, "The capacitance of a single isolated spherical conductor with radius $R$ is proportional to:",
    ["$R$", "$R^2$", "$1/R$", "$1/R^2$", "none of these"], "A",
    r"$V = \frac{kQ}{R} \Rightarrow C = \frac{Q}{V} = 4\pi\varepsilon_0 R$, proportional to $R$."),
  M(5, r"A parallel-plate capacitor has plate area 0.3 m² and separation 0.1 mm. If each plate has charge $5\times10^{-6}$ C, the force one plate exerts on the other is about:",
    ["5 N", "9 N", r"$1\times10^{4}$ N", r"$9\times10^{5}$ N", r"$2\times10^{7}$ N"], "A",
    r"Each plate feels the field of the OTHER plate only, $\frac{\sigma}{2\varepsilon_0}$: $F = Q\frac{\sigma}{2\varepsilon_0} = \frac{Q^2}{2\varepsilon_0A} = \frac{(5\times10^{-6})^2}{2(8.85\times10^{-12})(0.3)} \approx 5$ N.",
    r"""Two ways to see it. (1) The field of ONE plate is $\sigma/2\varepsilon_0$, so the force on the other plate is $$F = Q\cdot\frac{\sigma}{2\varepsilon_0} = \frac{Q^2}{2\varepsilon_0 A}.$$ (2) The official solution uses energy: $U = \frac{Q^2}{2C} = \frac{Q^2 d}{2\varepsilon_0 A}$, and pulling the plates apart by $d$ takes work $F\,d$, so $F = \frac{Q^2}{2\varepsilon_0 A}$. Numbers: $$F = \frac{25\times10^{-12}}{2(8.85\times10^{-12})(0.3)} = 4.7 \approx 5\ \text{N}.$$ **Why this method:** using the full field between the plates, $\sigma/\varepsilon_0$, would double-count, because a plate can't push on itself."""),
  M(6, "A 2 μF and a 1 μF capacitor are connected in parallel across a potential difference. The 2 μF capacitor has:",
    ["twice the charge of the 1 μF capacitor", "half the charge of the 1 μF capacitor", "twice the potential difference of the 1 μF capacitor",
     "half the potential difference of the 1 μF capacitor", "none of the above"], "A",
    r"In parallel they share the same $V$, and $Q = CV$, so double the capacitance means double the charge."),
  M(7, "Each of the three 25 μF capacitors shown is initially uncharged. How many coulombs pass through the ammeter A after the switch S is closed?",
    ["0.033 C", "0.10 C", "0.30 C", "10 C", "none of these"], "C",
    r"The three capacitors are in parallel across the 4000 V battery: $C_{eq} = 3(25\ \mu\text{F}) = 75$ μF, so $Q = C_{eq}V = (75\times10^{-6})(4000) = 0.30$ C.",
    fig=F("q7")),
  M(8, r"$C_1$ is charged alone to $4.0\times10^{-8}$ C, removed from the battery and connected to $C_2$ and $C_3$ as shown. The charge on the positive plate of $C_1$ becomes $1.0\times10^{-8}$ C. The charges on the positive plates of $C_2$ and $C_3$ are:",
    [r"$q_2 = 3.0\times10^{-8}$, $q_3 = 3.0\times10^{-8}$ C", r"$q_2 = 2.0\times10^{-8}$, $q_3 = 2.0\times10^{-8}$ C", r"$q_2 = 5.0\times10^{-8}$, $q_3 = 1.0\times10^{-8}$ C",
     r"$q_2 = 3.0\times10^{-8}$, $q_3 = 1.0\times10^{-8}$ C", r"$q_2 = 1.0\times10^{-8}$, $q_3 = 3.0\times10^{-8}$ C"], "A",
    r"Charge is conserved: $4.0 - 1.0 = 3.0\times10^{-8}$ C left $C_1$ and went onto the series pair $C_2$–$C_3$. Capacitors in series carry the SAME charge, so $q_2 = q_3 = 3.0\times10^{-8}$ C.",
    fig=F("q8")),
  M(9, "A charged capacitor stores 10 C at 40 V. Its stored energy is:",
    ["400 J", "200 J", "4 J", "2.5 J", "1.25 J"], "B",
    r"$U = \tfrac12 QV = \tfrac12(10)(40) = 200$ J. (Not $QV$: the voltage builds up from 0 to $V$ while charging.)"),
  M(10, "Capacitors A and B are identical. A stores 4 J and B is uncharged. They are then connected in parallel. The total stored energy is now:",
    ["16 J", "8 J", "4 J", "2 J", "1 J"], "D",
    r"The charge $Q$ splits equally, $Q/2$ each. $U = 2\cdot\frac{(Q/2)^2}{2C} = \frac12\cdot\frac{Q^2}{2C} = \frac12(4\ \text{J}) = 2$ J. The other 2 J is lost (as heat or radiation) when the charge rushes between them."),
  M(11, "A 5.0 μF capacitor is charged to 5 mC and isolated; then its plates are brought closer so its capacitance becomes 10 μF. The work done by the agent is about:",
    ["0 J", r"$1.25\times10^{-6}$ J", r"$-1.25\times10^{-6}$ J", r"$8.3\times10^{-7}$ J", r"$-8.3\times10^{-7}$ J"], "C",
    r"Isolated, so $Q$ is fixed: $W = \Delta U = \frac{Q^2}{2C'} - \frac{Q^2}{2C}$, negative because the plates attract (the agent holds them back).",
    r"""With $Q$ fixed, $W_{\text{agent}} = \Delta U = \frac{Q^2}{2}\left(\frac{1}{C'} - \frac{1}{C}\right)$. **[NOTE]** With $Q = 5$ mC this gives $\frac{(5\times10^{-3})^2}{2}\left(\frac{1}{10^{-5}} - \frac{1}{5\times10^{-6}}\right) = -1.25$ J, not the official $-1.25\times10^{-6}$ J. The official answer matches $Q = 5$ **μC**: $\frac{(5\times10^{-6})^2}{2}(10^5 - 2\times10^5) = -1.25\times10^{-6}$ J. The sign (negative) and the method are the same either way. **Why this method:** with the charge fixed, use $U = Q^2/2C$, the form where $Q$ stays constant.""",
    note="Answer key assumes 5 μC; with 5 mC the work is −1.25 J."),
  M(12, "A battery charges a parallel-plate capacitor and is then disconnected. The plates are pulled apart to twice their separation. This doubles the:",
    ["capacitance", "surface charge density on each plate", "stored energy", "electric field between the plates", "charge on each plate"], "C",
    r"Disconnected, so $Q$ (and $\sigma$, and $E = \sigma/\varepsilon_0$) stay the same. $C = \varepsilon_0A/d$ halves, so $U = \frac{Q^2}{2C}$ doubles."),
  M(13, r"A parallel-plate capacitor has plate area 0.30 m² and separation 0.10 mm. If each plate has charge $5.0\times10^{-6}$ C, what is the energy density in its field?",
    ["0.16 J/m³", "3.5 J/m³", "7.8 J/m³", "16 J/m³", "24 J/m³"], "D",
    r"$u = \tfrac12\varepsilon_0E^2$ with $E = \frac{\sigma}{\varepsilon_0} = \frac{Q}{\varepsilon_0A}$: $u = \frac{Q^2}{2\varepsilon_0A^2} = \frac{25\times10^{-12}}{2(8.85\times10^{-12})(0.09)} = 16$ J/m³."),
  M(14, "An air-filled parallel-plate capacitor has $C = 1$ pF. The separation is doubled and wax completely fills the gap; the capacitance becomes 2 pF. The dielectric constant of the wax is:",
    ["0.25", "0.50", "2.0", "4.0", "8.0"], "D",
    r"$C' = \kappa\frac{\varepsilon_0A}{2d} = \frac{\kappa}{2}(1\ \text{pF}) = 2$ pF $\Rightarrow \kappa = 4$."),
  M(15, "An air-filled capacitor is charged, then a dielectric is inserted, and an induced charge appears on the dielectric. What is the difference between induced charge and free charge?",
    ["There is no difference.", "Induced charge does not result in a net charge on the dielectric.", "Induced charge is smaller than free charge.",
     "Free charge creates an electric field, but induced charge does not.", "Free charge creates an electric potential, but induced charge does not."], "B",
    "Induced (bound) charge comes from molecules polarizing: equal + and − layers on opposite faces, so the dielectric stays neutral overall. Both kinds of charge produce fields; that's why the field inside drops."),
  M(16, r"Determine the energy stored in $C_2$ when $C_1 = 15$ μF, $C_2 = 10$ μF, $C_3 = 20$ μF and $V_0 = 18$ V (circuit shown).",
    ["0.72 mJ", "0.32 mJ", "0.50 mJ", "0.18 mJ", "1.60 mJ"], "D",
    r"$C_2 \parallel C_3 = 30$ μF, in series with $C_1 = 15$ μF. Series pieces share $Q$, so $V$ splits inversely to $C$: $V_{23} = 18\cdot\frac{15}{45} = 6$ V. $U_2 = \tfrac12(10\times10^{-6})(6)^2 = 0.18$ mJ.",
    fig=F("q16")),
  M(17, "A 30 μF capacitor is charged to 80 V and then connected across an uncharged capacitor $C$. The final potential difference across the 30 μF capacitor is 20 V. Determine $C$.",
    ["60 μF", "75 μF", "45 μF", "90 μF", "24 μF"], "D",
    r"Charge is conserved and the final voltages are equal: $(30\ \mu\text{F})(80\ \text{V}) = (30\ \mu\text{F} + C)(20\ \text{V}) \Rightarrow C = 90$ μF.",
    r"""$$Q_0 = (30\times10^{-6})(80) = 2.4\times10^{-3}\ \text{C} = (30\times10^{-6} + C)(20) \;\Rightarrow\; C = 120 - 30 = 90\ \mu\text{F}.$$ **[NOTE]** The official working ends with "C = 9 μF", but its chosen answer, D (90 μF), is correct. **Why this method:** connected capacitors end at the same voltage, and no charge is lost."""),
  M(18, "A capacitor $C_0$ connected to a battery $V_0$ has charge $Q_0$. While still connected, its gap is filled with a dielectric of constant 3. Afterwards the charge and potential difference are:",
    [r"$\frac13Q_0, \frac13V_0$", r"$Q_0, \frac13V_0$", "$Q_0, V_0$", "$3Q_0, V_0$", "$3Q_0, 3V_0$"], "D",
    r"The battery holds $V = V_0$. The capacitance triples, $C = 3C_0$, so $Q = CV_0 = 3Q_0$."),
  M(19, "A capacitor $C_0$ is charged to $V_0$ by a battery, then disconnected, and its gap is filled with a dielectric of constant 3. Afterwards the capacitance and potential difference are:",
    [r"$\frac13C_0, \frac13V_0$", r"$C_0, \frac13V_0$", "$C_0, V_0$", r"$3C_0, \frac13V_0$", "$3C_0, 3V_0$"], "D",
    r"Disconnected, so $Q = Q_0$ is fixed. $C = 3C_0$, so $V = \frac{Q_0}{3C_0} = \frac13V_0$."),
  M(20, r"Horizontal plates, capacitance $C_0$. A dielectric slab with $\kappa = 2$ fills the bottom half of the gap. The new capacitance is:",
    [r"$\frac25C_0$", r"$\frac34C_0$", "$4C_0$", r"$\frac52C_0$", r"$\frac43C_0$"], "E",
    r"Two capacitors in SERIES, each with gap $d/2$: air $2C_0$ and dielectric $2\kappa C_0 = 4C_0$. $\frac1C = \frac1{2C_0} + \frac1{4C_0} = \frac{3}{4C_0} \Rightarrow C = \frac43C_0$."),
  P(21, r"Problem 1. The plates of a parallel-plate capacitor in vacuum are $5.00\times10^{-3}$ m apart with area 2.00 m². A $1.0\times10^4$ V potential difference is applied. Compute (a) the capacitance, (b) the charge on each plate, (c) the magnitude of the field between the plates.",
    [part("(a)", "", "$C = 3.54$ nF",
      r"$C = \frac{\varepsilon_0A}{d} = \frac{(8.85\times10^{-12})(2.00)}{5.00\times10^{-3}} = 3.54\times10^{-9}$ F.", "Parallel-plate formula."),
     part("(b)", "", r"$Q = 35.4$ μC",
      r"$Q = CV = (3.54\times10^{-9})(1.0\times10^4) = 3.54\times10^{-5}$ C.", "Definition $C = Q/V$."),
     part("(c)", "", r"$E = 2.00\times10^{6}$ N/C",
      r"$E = \frac{V}{d} = \frac{1.0\times10^4}{5.00\times10^{-3}} = 2.00\times10^6$ N/C, or equally $E = \frac{\sigma}{\varepsilon_0} = \frac{Q}{\varepsilon_0A}$.",
      "Uniform field: $V = Ed$.")]),
  P(22, r"Problem 2. With $C_1 = 6.0$ μF, $C_2 = 3.0$ μF and $V_{ab} = 18$ V, the capacitors are connected in SERIES. Find (a) the equivalent capacitance, (b) the charge and potential difference for each capacitor.",
    [part("(a)", "", r"$C_{eq} = 2.0$ μF",
      r"$\frac1{C_{eq}} = \frac1{6.0} + \frac1{3.0} = \frac12 \Rightarrow C_{eq} = 2.0$ μF.", "Series: reciprocals add."),
     part("(b)", "", r"$Q = 36$ μC each; $V_1 = 6.0$ V, $V_2 = 12.0$ V",
      r"In series every capacitor carries the same charge: $Q = C_{eq}V = (2.0)(18) = 36$ μC. Then $V_1 = Q/C_1 = 6.0$ V and $V_2 = Q/C_2 = 12.0$ V (they add to 18 V).",
      "Same $Q$ in series; the smaller capacitor takes the bigger voltage.")],
    fig=F("p2")),
  P(23, r"Problem 3. With $C_1 = 6.0$ μF, $C_2 = 3.0$ μF and $V_{ab} = 18$ V, the capacitors are connected in PARALLEL. Find (a) the equivalent capacitance, (b) the charge and potential difference for each capacitor.",
    [part("(a)", "", r"$C_{eq} = 9.0$ μF", r"$C_{eq} = C_1 + C_2 = 9.0$ μF.", "Parallel: capacitances add."),
     part("(b)", "", r"$V = 18$ V each; $Q_1 = 108$ μC, $Q_2 = 54$ μC",
      r"Both see the full 18 V: $Q_1 = (6.0)(18) = 108$ μC, $Q_2 = (3.0)(18) = 54$ μC.", "Same $V$ in parallel; charge follows capacitance.")],
    fig=F("p3")),
  P(24, r"Problem 4. In the figure, each capacitor has $C = 4.00$ μF. Calculate the equivalent capacitance (a) between $a$ and $d$, (b) between $a$ and $b$.",
    [part("(a)", "", r"$C_{ad} = 6.0$ μF",
      r"$C_1$ and $C_2$ in series: $C_{12} = 2.0$ μF. That is in parallel with $C_3$: $C_{ad} = 2.0 + 4.0 = 6.0$ μF.", "Reduce step by step, innermost group first."),
     part("(b)", "", r"$C_{ab} = 2.4$ μF",
      r"$C_{ad}$ is in series with $C_4$: $\frac1{C_{ab}} = \frac16 + \frac14 \Rightarrow C_{ab} = 2.4$ μF.", "Series combination of the result from (a) with $C_4$.")],
    fig=F("p4")),
])
